/*
共享 runtime 上下文概述
- 默认与 Vapor 入口共用活动 runtime 切换，保证嵌套调用结束后恢复先前上下文。
- 本模块不依赖 DOM/runtime 创建模块，因此 DOM 事件也能复用同一激活原语。
*/

const canTrackRuntime = (runtime: unknown): runtime is object =>
  (typeof runtime === 'object' || typeof runtime === 'function') && runtime != null

type RuntimeContextGlobal = typeof globalThis & {
  __rue_active?: unknown
  __rue?: unknown
}

const runtimeGlobal = globalThis as RuntimeContextGlobal

/** 在存在活动 runtime 时使用它，否则按调用方规则解析默认实例。 */
export const resolveActiveRuntime = <T>(fallback: () => T): T => {
  const activeRuntime = runtimeGlobal.__rue_active
  return canTrackRuntime(activeRuntime) ? (activeRuntime as T) : fallback()
}

/** 从当前活动 runtime（或默认 runtime）读取挂载容器，不依赖 runtime 总入口。 */
export const getCurrentContainer = () => {
  const runtime = resolveActiveRuntime(() => runtimeGlobal.__rue) as {
    getCurrentContainer?: () => unknown
  } | null
  return typeof runtime?.getCurrentContainer === 'function' ? runtime.getCurrentContainer() : null
}

/** 临时切换当前激活 runtime，并在 runner 结束后恢复。 */
export const runWithRuntime = <T>(runtime: unknown, runner: () => T): T => {
  if (!canTrackRuntime(runtime)) {
    return runner()
  }

/*
 * [RUE-MOUNT-023] 应用挂载 · 步骤 23：runWithRuntime()：保存旧活动 runtime，设置新值
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=23
 * 所在阶段：B · 开始挂载：解析容器 → 执行 runner；节点类型：调用。
 *   1. 对于非空对象或函数，先记录全局是否原本有 __rue_active 自有属性，再保存它原来的值 previousRuntime。
 *   2. 把 __rue_active 设为当前 runtime；后续同步回调执行期间，读取活动 runtime 会看到这个值。
 *   3. 执行 try 中的 runner()，这里 runner 是 contextRunner。finally 暂时还不能执行，要等这个回调返回或抛错。
 * 执行结果：进入 client-runtime.ts 的容器上下文回调。原活动值保留在当前调用帧里，之后会恢复。
 * 衔接说明：这里 runWithRuntime 的形参 runner = contextRunner，和 runWithClientRuntime 的 runner 不是同一个函数。
 * 断点观察：看 hadActiveRuntime、previousRuntime 和新的 __rue_active；不要把全局默认 __rue 与临时活动 __rue_active 混淆。
 */
  const hadActiveRuntime = Object.prototype.hasOwnProperty.call(runtimeGlobal, '__rue_active')
  const previousRuntime = runtimeGlobal.__rue_active
  runtimeGlobal.__rue_active = runtime
  try {
    console.log('dzy第一个打印出来')
    return runner()
  } finally {
/*
 * [RUE-MOUNT-102] 应用挂载 · 步骤 102：runWithRuntime finally：恢复原活动 runtime
 * 对应指南：RUE_SOURCE_GUIDE.html#flow=mount&view=sequence&node=102
 * 所在阶段：F · 提交 #app → 生命周期 → 逐层返回；节点类型：返回。
 *   1. hadActiveRuntime 为 true 时，恢复 previousRuntime。即使旧值本来是 undefined，也保留原本存在的属性。
 *   2. 原先没有 __rue_active 自有属性时，使用 delete 删除本次临时添加的属性。
 *   3. finally 完成后，runWithRuntime 和 runWithClientRuntime 依次返回 useApp.mount。
 * 执行结果：运行时与容器的临时上下文都已恢复，外层 mount 可以继续确认应用容器。
 * 衔接说明：恢复 previousRuntime；原先没有该属性则删除。再返回 runWithClientRuntime，最终回到 useApp.mount。
 * 断点观察：不仅比较 __rue_active 的值，也检查 hasOwnProperty；“没有属性”和“属性值为 undefined”不同。
 */
    if (hadActiveRuntime) {
      runtimeGlobal.__rue_active = previousRuntime
    } else {
      delete runtimeGlobal.__rue_active
    }
  }
}
